<!DOCTYPE html>
<html>
<head>
  <title>Bouncing Ball Playground</title>
  <style>
    body {
      background-color: #1e1e1e;
      color: #f0f0f0;
      font-family: sans-serif;
    }

    #sim {
      border: 1px solid #555;
      margin: 20px auto;
      background-color: #333;
    }

    button {
      background-color: #444;
      color: #f0f0f0;
      padding: 8px 16px;
      border: none;
      cursor: pointer;
      margin: 5px;
    }

    button:hover {
      background-color: #666;
    }
  </style>
</head>
<body>
  <h1>Bouncing Ball Playground</h1>

  <canvas id="sim"></canvas>

  <button id="drop">Drop Ball</button>
  <button id="play">Play</button>
  <button id="clear">Clear</button>

  <script>
    const canvas = document.getElementById('sim');
    const ctx = canvas.getContext('2d');
    const dropButton = document.getElementById('drop');
    const playButton = document.getElementById('play');
    const clearButton = document.getElementById('clear');

    let balls = [];
    let running = false;
    const w = canvas.width;
    const h = canvas.height;
    const dt = 16; // Frames per second (approximate)

    function addBall(x, y, vx=0, vy=0, r=10) {
      balls.push({ x, y, vx, vy, r });
    }

    function clearBalls() {
      balls = [];
    }

    function step(dt) {
      for (const ball of balls) {
        // Gravity
        ball.vy += dt * 0.5; // Adjust gravity constant as needed

        // Bounce off floor
        if (ball.y + ball.r > h) {
          ball.y = h - ball.r;
          ball.vy *= -0.8; // Restitution coefficient (adjust for energy loss)
        }

        // Bounce off walls
        if (ball.x - ball.r < 0 || ball.x + ball.r > w) {
          ball.x = ball.r + (ball.x - ball.r < 0 ? w - ball.r : ball.r);
          ball.vx *= -0.8; // Restitution coefficient
        }

        if (ball.y - ball.r < 0) {
          ball.y = ball.r;
          ball.vy *= -0.8; // Restitution coefficient
        }


        // Update position
        ball.x += ball.vx * dt;
        ball.y += ball.vy * dt;
      }

      // Draw balls
      ctx.clearRect(0, 0, w, h);
      for (const ball of balls) {
        ctx.beginPath();
        ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
        ctx.fillStyle = '#ffcc66'; // Yellow color for the balls
        ctx.fill();
        ctx.closePath();
      }
    }

    dropButton.addEventListener('click', () => {
      addBall(Math.random() * w - w / 2, Math.random() * h - h / 2);
    });

    playButton.addEventListener('click', () => {
      running = true;
      let lastTime = performance.now();
      function animate() {
        const currentTime = performance.now();
        const elapsedTime = currentTime - lastTime;

        step(elapsedTime / 1000); //dt is already defined as 16 for visual accuracy
        lastTime = currentTime;

        if (running) {
          requestAnimationFrame(animate);
        }
      }
      animate();
    });

    clearButton.addEventListener('click', () => {
      clearBalls();
    });


    window.sim = {
      w,
      h,
      balls,
      addBall,
      clear,
      step,
    };
  </script>
</body>
</html>
